// The `scan` command is WebView-facing (the JoinFlow invokes it), so it IS
// listed here — `tauri_plugin::Builder` autogenerates its `allow-scan` /
// `deny-scan` permissions under `permissions/autogenerated/`. `ios_path` wires
// the `ios/` Swift package into the app's generated Xcode project; on Android /
// desktop hosts it is inert (the plugin is iOS-only, SYNC-46 — Android is
// MYND-465).
const COMMANDS: &[&str] = &["scan"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").build();
}
